 90	    private Xzj27 createAndSaveOrderBid(Xrd81 user, Xdh20 productSize, int bidPrice, Xdg64 order) {
 91	        Xzj27 orderBid = Xzj27.builder()
 92	                .user(user)
 93	                .productSize(productSize)
 94	                .bidPrice(bidPrice)
 95	                .status(Xtz73Status.PENDING)
 96	                .order(order)
 97	                .build();
 98	
 99	
100	        orderBid.assignOrder(order);
101	
102	        return orderBidRepository.save(orderBid);
103	    }
