189	    private Xzj27 createInstantOrderBid(Xdg64 order, Xzz58 saleBid, Xgg74 sale) {
190	        Xdh20 productSize = saleBid.getProductSize();
191	
192	        Xzj27 orderBid = Xzj27.builder()
193	                .user(order.getUser())
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(Xtz73Status.MATCHED)
197	                .order(order)
198	                .sale(sale)
199	                .build();
200	
201	
202	        orderBid.assignOrder(order);
203	
204	
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
