227	    @Transactional
228	    public void matchOrderBid(Xzj27 orderBid) {
229	        try {
230	            if (orderBid == null) {
231	                throw new Xvt58Exception("주문 입찰 정보가 없습니다.");
232	            }
233	
234	            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
235	                throw new Xmd85Exception("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
236	            }
237	
238	            orderBid.updateStatus(Xtz73Status.MATCHED);
239	        } catch (Exception e) {
240	            if (e instanceof Xdg64Exception) {
241	                throw e;
242	            }
243	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
244	            throw new Xhz43Exception("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
245	        }
246	    }
