256	    @Transactional
257	    public void deleteOrderBid(Long orderBidId) {
258	        try {
259	
260	            Xzj27 orderBid = orderBidRepository.findById(orderBidId)
261	                    .orElseThrow(() -> new Xvt58Exception("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
262	
263	
264	            if (orderBid.getSale() != null) {
265	                throw new Xmd85Exception("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
266	            }
267	
268	
269	            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
270	                throw new Xmd85Exception("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
271	            }
272	
273	
274	            if (orderBid.getOrder() != null) {
275	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
276	            }
277	
278	
279	            orderBidRepository.delete(orderBid);
280	        } catch (Exception e) {
281	            if (e instanceof Xdg64Exception) {
282	                throw e;
283	            }
284	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
285	            throw new Xdw92Exception("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
286	        }
287	    }
